import { apiBaseUrl, inqaccDefaultToken, requestTimeoutMs } from '../config/env'
import type { AccountErrorEnvelope, AccountInquiryRequest, AccountInquiryResult, AccountResponse } from '../domain/accountTypes'

export async function inquireAccount(request: AccountInquiryRequest): Promise<AccountInquiryResult> {
  const controller = new AbortController()
  const timeout = setTimeout(() => controller.abort(), requestTimeoutMs)

  try {
    const response = await fetch(
      `${apiBaseUrl}/v1/accounts/${request.sortcode}/${request.accountNumber}`,
      {
        signal: controller.signal,
        headers: {
          Authorization: `Bearer ${inqaccDefaultToken}`,
        },
      },
    )

    const correlationId = response.headers.get('X-Correlation-ID') ?? ''

    if (response.status === 200) {
      const data = (await response.json()) as AccountResponse
      return {
        type: 'success',
        status: 200,
        data,
        correlationId,
      }
    }

    const errorEnvelope = await safeParseError(response, correlationId)

    if (response.status === 404) {
      return {
        type: 'not-found',
        status: 404,
        error: errorEnvelope,
        correlationId,
      }
    }

    if (response.status === 400 || response.status === 401 || response.status === 403 || response.status === 500 || response.status === 503) {
      return {
        type: 'backend-error',
        status: response.status,
        error: errorEnvelope,
        correlationId,
      }
    }

    return {
      type: 'backend-error',
      status: 500,
      error: errorEnvelope,
      correlationId,
    }
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') {
      return { type: 'timeout', message: 'The account inquiry request timed out. Please retry.' }
    }

    return { type: 'network-error', message: 'Network unavailable. Check connection and retry.' }
  } finally {
    clearTimeout(timeout)
  }
}

async function safeParseError(response: Response, correlationId: string): Promise<AccountErrorEnvelope> {
  try {
    return (await response.json()) as AccountErrorEnvelope
  } catch {
    return {
      error: {
        code: 'ERR-006',
        message: 'Unexpected internal failure',
        timestamp: new Date().toISOString(),
        correlationId,
      },
    }
  }
}

import { apiBaseUrl, inqaccDefaultToken, requestTimeoutMs } from '../config/env'
import type { StatementErrorResponse, StatementInquiryResult, StatementRequest, StatementResponse } from '../domain/statementTypes'

export async function inquireStatement(request: StatementRequest): Promise<StatementInquiryResult> {
  const controller = new AbortController()
  const timeout = setTimeout(() => controller.abort(), requestTimeoutMs)

  try {
    const url = `${apiBaseUrl}/api/v1/accounts/${request.sortCode}/${request.accountNumber}/statements/${request.period}`
    const response = await fetch(url, {
      signal: controller.signal,
      headers: {
        Authorization: `Bearer ${inqaccDefaultToken}`,
      },
    })

    const correlationId = response.headers.get('X-Correlation-ID') ?? ''

    if (response.status === 200) {
      const data = (await response.json()) as StatementResponse
      return {
        type: 'success',
        status: 200,
        data,
        correlationId,
      }
    }

    if (response.status === 400 || response.status === 401 || response.status === 403 || response.status === 404 || response.status === 500) {
      const error = await safeParseError(response, correlationId)
      return {
        type: 'backend-error',
        status: response.status,
        error,
        correlationId,
      }
    }

    return {
      type: 'backend-error',
      status: 500,
      error: {
        code: 'ERR-500',
        message: 'Service unavailable due to infrastructure failure',
        correlationId,
      },
      correlationId,
    }
  } catch (error) {
    if (error instanceof DOMException && error.name === 'AbortError') {
      return { type: 'timeout', message: 'The statement inquiry request timed out. Please retry.' }
    }

    return { type: 'network-error', message: 'Network unavailable. Check connection and retry.' }
  } finally {
    clearTimeout(timeout)
  }
}

async function safeParseError(response: Response, correlationId: string): Promise<StatementErrorResponse> {
  try {
    return (await response.json()) as StatementErrorResponse
  } catch {
    return {
      code: 'ERR-500',
      message: 'Service unavailable due to infrastructure failure',
      correlationId,
    }
  }
}

@RestControllerAdvice(basePackageClasses = AccountInquiryController.class)
@Order(Ordered.HIGHEST_PRECEDENCE)
public class AccountInquiryExceptionHandler {

    private static final Logger LOGGER = LoggerFactory.getLogger(AccountInquiryExceptionHandler.class);

    @ExceptionHandler(IllegalArgumentException.class)
    public ResponseEntity<ErrorResponse> handleValidation(IllegalArgumentException exception) {
        LOGGER.warn("event=inqacc_inquiry_error status=400 code=ERR-001");
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(error("ERR-001", exception.getMessage(), null));
    }

    @ExceptionHandler(BadCredentialsException.class)
    public ResponseEntity<ErrorResponse> handleUnauthorized(BadCredentialsException exception) {
        LOGGER.warn("event=inqacc_inquiry_error status=401 code=ERR-002");
        return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                .body(error("ERR-002", "Unauthorized", null));
    }

    @ExceptionHandler(AccessDeniedException.class)
    public ResponseEntity<ErrorResponse> handleForbidden(AccessDeniedException exception) {
        LOGGER.warn("event=inqacc_inquiry_error status=403 code=ERR-003");
        return ResponseEntity.status(HttpStatus.FORBIDDEN)
                .body(error("ERR-003", "Forbidden", null));
    }

    @ExceptionHandler(AccountNotFoundException.class)
    public ResponseEntity<ErrorResponse> handleNotFound(AccountNotFoundException exception) {
        LOGGER.info("event=inqacc_inquiry_error status=404 code=ERR-004");
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
                .body(error("ERR-004", exception.getMessage(), null));
    }

    @ExceptionHandler(RepositoryUnavailableException.class)
    public ResponseEntity<ErrorResponse> handleRepositoryUnavailable(RepositoryUnavailableException exception) {
        LOGGER.warn("event=inqacc_inquiry_error status=503 code=ERR-005");
        return ResponseEntity.status(HttpStatus.SERVICE_UNAVAILABLE)
                .body(error("ERR-005", "Repository unavailable", null));
    }

